const ErrorState = ({ message, onRetry }) => (
  <Centered><AlertTriangle size={22} /><p>{message}</p>
    {onRetry && <button className="btn-ghost" onClick={onRetry}>إعادة المحاولة</button>}
  </Centered>
);
const Empty = ({ icon: Icon = Package, text }) => (
  <Centered><Icon size={24} /><p>{text}</p></Centered>
);
const BrandMark = ({ size = 28 }) => (
  <img src={LOGO_MARK} alt="جملة" style={{ height: size, width: "auto", display: "block" }} />
);

function SearchBar({ value, onChange, placeholder, inline }) {
  return (
    <div className={"search-bar" + (inline ? " search-bar-inline" : "")}>
      <Search size={16} />
      <input placeholder={placeholder} value={value} onChange={(e) => onChange(e.target.value)} />
      {value && <button className="search-clear" onClick={() => onChange("")}><X size={15} /></button>}
    </div>
  );
}

function Stat({ label, value, debt }) {
  return (
    <div className={"stat-box" + (debt ? " stat-box-debt" : "")}>
      <span>{label}</span><b>{value}</b>
    </div>
  );
}

/* --------------------------- الدخول --------------------------- */

function LoginView({ onRequestOtp, onVerify }) {
  const [step, setStep] = useState("phone");
  const [phone, setPhone] = useState("");
  const [digits, setDigits] = useState(["", "", "", ""]);
  const [seconds, setSeconds] = useState(0);
  const refs = useRef([]);
  const send = useAction(onRequestOtp);
  const verify = useAction(onVerify);

  useEffect(() => {
    if (step !== "otp" || seconds <= 0) return;
    const t = setTimeout(() => setSeconds((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [step, seconds]);
  useEffect(() => { if (step === "otp") refs.current[0]?.focus(); }, [step]);

  async function handleSend() {
    if (phone.replace(/\D/g, "").length < 9) return;
    await send.run(phone).catch(() => {});
    setSeconds(30); setStep("otp");
  }

  return (
    <div className="login-screen">
      <img src={LOGO_FULL} alt="جملة" className="brand-logo-full" />
      <p className="login-sub">لوحة الإدارة — منصة جملة لتجارة الجملة</p>

      {step === "phone" ? (
        <div className="login-card">
          <label className="field-label">رقم حساب الإدارة</label>
          <input className="field-input" placeholder="09XXXXXXXX" value={phone} dir="ltr"
            style={{ textAlign: "right" }} inputMode="numeric"
            onChange={(e) => setPhone(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSend()} />
          {send.error && <p className="field-error">{send.error}</p>}
          <button className="btn-primary" onClick={handleSend} disabled={send.pending}>
            {send.pending ? "جارٍ الإرسال…" : "إرسال رمز التحقق"}
          </button>
          <p className="login-note">{COMPANY.address}</p>
        </div>
      ) : (
        <div className="login-card">
          <label className="field-label">رمز التحقق المُرسل إلى {phone}</label>
          <div className="otp-row" dir="ltr">
            {digits.map((d, i) => (
              <input key={i} ref={(el) => (refs.current[i] = el)} className="otp-box" value={d}
                type="tel" inputMode="numeric" maxLength={1}
                autoComplete={i === 0 ? "one-time-code" : "off"}
                onFocus={(e) => e.target.select()}
                onChange={(e) => {
                  const v = e.target.value.replace(/\D/g, "").slice(-1);
                  const next = [...digits]; next[i] = v; setDigits(next);
                  if (v && i < 3) refs.current[i + 1]?.focus();
                }}
                onKeyDown={(e) => e.key === "Backspace" && !digits[i] && i > 0 && refs.current[i - 1]?.focus()} />
            ))}
          </div>
          {verify.error && <p className="field-error">{verify.error}</p>}
          <button className="btn-primary" disabled={verify.pending || digits.join("").length < 4}
            onClick={() => verify.run(phone, digits.join("")).catch(() => {})}>
            {verify.pending ? "جارٍ التحقق…" : "تأكيد الدخول"}
          </button>
          <div className="otp-footer">
            <button className="link-btn" onClick={() => setStep("phone")}>تعديل الرقم</button>
            <button className="link-btn" disabled={seconds > 0} onClick={handleSend}>
              {seconds > 0 ? `إعادة الإرسال بعد ${seconds} ث` : "إعادة إرسال الرمز"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* -------------------------- القائمة -------------------------- */

function AdminNotificationBell() {
  const [open, setOpen] = useState(false);
  const { data, loading, reload } = useFetch(() => api.notifications(), []);

  useEffect(() => {
    const t = setInterval(reload, 30000);
    return () => clearInterval(t);
  }, []);

  const unreadCount = data?.unreadCount ?? 0;

  function markRead(n) {
    if (n.in_app_read_at) return;
    api.markNotificationRead(n.id).then(reload).catch(() => {});
  }
  function markAll() {
    api.markAllNotificationsRead().then(reload).catch(() => {});
  }

  return (
    <div style={{ position: "relative" }}>
      <button className="sidebar-link" onClick={() => setOpen((o) => !o)} style={{ position: "relative" }}>
        <Bell size={18} /><span>الإشعارات</span>
        {unreadCount > 0 && <span className="notif-badge">{unreadCount > 9 ? "9+" : unreadCount}</span>}
      </button>
      {open && (
        <div className="notif-panel" style={{ position: "absolute", top: 0, right: "100%", marginRight: 8 }}>
          <div className="notif-panel-head">
            <span>الإشعارات</span>
            {unreadCount > 0 && <button className="link-btn" onClick={markAll}>تعليم الكل كمقروء</button>}
          </div>
          {loading ? <Spinner /> : !data?.notifications?.length ? (
            <p className="hint" style={{ padding: 12 }}>لا توجد إشعارات بعد</p>
          ) : (
            <div className="notif-list">
              {data.notifications.map((n) => (
                <div key={n.id} className={"notif-row" + (!n.in_app_read_at ? " notif-row-unread" : "")}
                  onClick={() => markRead(n)}>
                  <span className="notif-title">{n.title}</span>
                  <span className="notif-body">{n.body}</span>
                  <span className="notif-time">{new Date(n.created_at).toLocaleString("ar")}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

