/* ------------------------- الرئيسية ------------------------- */

function Dashboard({ onGo }) {
  const orders = useFetch((s) => api.orders(undefined, s), []);
  const treasuries = useFetch((s) => api.treasuries(s).catch(() => []), []);

  if (orders.loading) return <Spinner />;
  if (orders.error) return <ErrorState message={orders.error} onRetry={orders.reload} />;

  const list = orders.data ?? [];
  const today = new Date().toISOString().slice(0, 10);
  const todays = list.filter((o) => day(o.created_at) === today);
  const pending = list.filter((o) => o.status === "under_review");
  const revenue = todays.reduce((s, o) => s + Number(o.grand_total), 0);
  const recent = [...list].sort((a, b) => (a.created_at < b.created_at ? 1 : -1)).slice(0, 6);

  return (
    <div className="screen">
      <div className="stat-grid">
        <Stat label="طلبيات اليوم" value={todays.length} />
        <Stat label="إيرادات اليوم" value={money(revenue)} />
        <Stat label="بانتظار المراجعة" value={pending.length} debt />
        {(treasuries.data ?? []).map((t) => (
          <Stat key={t.id} label={`رصيد ${t.name}`} value={money(t.balance)} />
        ))}
      </div>

      {pending.length > 0 && (
        <button className="alert-banner" onClick={() => onGo("review")}>
          <AlertTriangle size={16} />
          <span>لديك {pending.length} {pending.length === 1 ? "طلبية" : "طلبيات"} بانتظار المراجعة والاعتماد</span>
        </button>
      )}

      <h2 className="subsection-heading">أحدث الطلبيات</h2>
      <OrdersTable orders={recent} onOpen={(id) => onGo("orderDetail", { orderId: id })} />
    </div>
  );
}

function OrdersTable({ orders, onOpen }) {
  if (!orders.length) return <Empty text="لا توجد طلبيات لعرضها" />;
  return (
    <table className="data-table">
      <thead>
        <tr>
          <th>رقم الفاتورة</th><th>العميل</th><th>التاريخ</th>
          <th>التسليم</th><th>الحالة</th><th>القيمة</th>
        </tr>
      </thead>
      <tbody>
        {orders.map((o) => (
          <tr className="data-row" key={o.id} onClick={() => onOpen(o.id)}>
            <td className="cell-id">{o.order_number}</td>
            <td>{o.customer_name}</td>
            <td className="cell-muted">{day(o.created_at)}</td>
            <td className="cell-muted">{o.fulfillment === "pickup" ? "استلام شخصي" : "توصيل"}</td>
            <td><span className={"status-pill" + (o.status === "cancelled" ? " status-pill-cancelled" : "")}>
              {statusLabel(o.status)}</span></td>
            <td className="cell-amount">{money(o.grand_total)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
/* أضف هذه الدالة في AdminApp.jsx — يفضّل بعد نهاية دالة ReviewQueue الحالية */

const ALL_STATUSES_FOR_BULK = [
  "under_review", "sent_to_supplier", "supplier_preparing", "shortage",
  "ready_for_delivery", "ready_for_pickup", "assigned_to_driver",
  "awaiting_pickup", "delivered", "postponed", "cancelled",
];

function AllOrdersView({ onOpen }) {
  const [status, setStatus] = useState("all");
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(new Set());
  const [targetStatus, setTargetStatus] = useState("");
  const [driverId, setDriverId] = useState("");
  const [showBulkForm, setShowBulkForm] = useState(false);

  const { data, loading, error, reload } = useFetch(
    (s) => api.orders(status === "all" ? undefined : { status }, s), [status]
  );
  const drivers = useFetch((s) => api.driversCash(s).catch(() => []), []);

  const needsDriver = targetStatus === "assigned_to_driver";
  const bulk = useAction(() => api.bulkOrderStatus({
    orderIds: [...selected], status: targetStatus,
    driverId: needsDriver ? driverId : undefined,
  }));

  const filters = [
    ["all", "الكل"], ["under_review", "قيد المراجعة"], ["sent_to_supplier", "مرسلة إلى المورد"],
    ["supplier_preparing", "قيد التجهيز"], ["shortage", "بها نقص"],
    ["ready_for_delivery", "جاهزة للتوصيل"], ["out_for_delivery", "في الطريق"],
    ["delivered", "تم التسليم"], ["cancelled", "ملغاة"],
  ];

  const visible = (data ?? []).filter(
    (o) => !query.trim() || o.order_number.toLowerCase().includes(query.trim().toLowerCase())
  );

  function toggleOne(id) {
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }
  function toggleAll() {
    setSelected((prev) =>
      prev.size === visible.length ? new Set() : new Set(visible.map((o) => o.id))
    );
  }
  function clearSelection() {
    setSelected(new Set());
    setShowBulkForm(false);
    setTargetStatus("");
    setDriverId("");
  }

  async function applyBulk() {
    if (!targetStatus) return;
    if (needsDriver && !driverId) return;
    const res = await bulk.run().catch(() => null);
    if (!res) return;
    reload();
    clearSelection();
    const msg = res.skippedCount
      ? `تم تحويل ${res.updatedCount} طلبية، وتخطي ${res.skippedCount} (راجع السبب لكل واحدة)`
      : `تم تحويل ${res.updatedCount} طلبية بنجاح`;
    alert(msg);
  }

  return (
    <div className="screen">
      <div className="toolbar-row">
        <div className="chip-row">
          {filters.map(([id, label]) => (
            <button key={id} className={"chip" + (status === id ? " chip-active" : "")}
              onClick={() => { setStatus(id); clearSelection(); }}>{label}</button>
          ))}
        </div>
        <SearchBar inline value={query} onChange={setQuery} placeholder="ابحث برقم الفاتورة..." />
      </div>

      {selected.size > 0 && (
        <div className="bulk-bar">
          <span>{selected.size} طلبية محددة</span>
          {showBulkForm ? (
            <div className="bulk-form-inline">
              <select className="field-input" style={{ marginBottom: 0, width: 190 }}
                value={targetStatus}
                onChange={(e) => { setTargetStatus(e.target.value); setDriverId(""); }}>
                <option value="">— اختر الحالة الجديدة —</option>
                {ALL_STATUSES_FOR_BULK.map((s) => (
                  <option key={s} value={s}>{statusLabel(s)}</option>
                ))}
              </select>

              {needsDriver && (
                <select className="field-input" style={{ marginBottom: 0, width: 170 }}
                  value={driverId} onChange={(e) => setDriverId(e.target.value)}>
                  <option value="">— اختر المندوب —</option>
                  {(drivers.data ?? []).map((d) => (
                    <option key={d.driver_id} value={d.driver_id}>{d.name}</option>
                  ))}
                </select>
              )}

              <button className="invoice-action-btn"
                disabled={!targetStatus || (needsDriver && !driverId) || bulk.pending}
                onClick={applyBulk}>
                {bulk.pending ? "جارٍ التحويل…" : "تأكيد التحويل"}
              </button>
              <button className="invoice-action-btn" onClick={() => setShowBulkForm(false)}>إلغاء</button>
            </div>
          ) : (
            <button className="invoice-action-btn" onClick={() => setShowBulkForm(true)}>
              تحويل الحالة دفعة واحدة
            </button>
          )}
          <button className="link-btn" onClick={clearSelection}>إلغاء التحديد</button>
        </div>
      )}
      {needsDriver && showBulkForm && (
        <p className="hint">التحويل لـ"في الطريق" يشمل فقط طلبيات التوصيل — طلبيات الاستلام الشخصي المحددة يتم تخطّيها تلقائيًا.</p>
      )}
      {bulk.error && <p className="field-error">{bulk.error}</p>}

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !visible.length ? <Empty text="لا توجد طلبيات مطابقة" />
       : (
        <table className="data-table">
          <thead>
            <tr>
              <th style={{ width: 34 }}>
                <input type="checkbox" checked={selected.size === visible.length && visible.length > 0}
                  onChange={toggleAll} />
              </th>
              <th>رقم الفاتورة</th><th>العميل</th><th>التاريخ</th>
              <th>التسليم</th><th>الحالة</th><th>القيمة</th>
            </tr>
          </thead>
          <tbody>
            {visible.map((o) => (
              <tr className="data-row" key={o.id}>
                <td onClick={(e) => e.stopPropagation()}>
                  <input type="checkbox" checked={selected.has(o.id)} onChange={() => toggleOne(o.id)} />
                </td>
                <td className="cell-id" onClick={() => onOpen(o.id)}>{o.order_number}</td>
                <td onClick={() => onOpen(o.id)}>{o.customer_name}</td>
                <td className="cell-muted" onClick={() => onOpen(o.id)}>{day(o.created_at)}</td>
                <td className="cell-muted" onClick={() => onOpen(o.id)}>
                  {o.fulfillment === "pickup" ? "استلام شخصي" : "توصيل"}
                </td>
                <td onClick={() => onOpen(o.id)}>
                  <span className={"status-pill" + (o.status === "cancelled" ? " status-pill-cancelled" : "")}>
                    {statusLabel(o.status)}
                  </span>
                </td>
                <td className="cell-amount" onClick={() => onOpen(o.id)}>{money(o.grand_total)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

/* أضف هذه الدالة في AdminApp.jsx — بعد AllOrdersView مباشرة (قبل OrdersHub) */

function CreateOrderView({ onCreated }) {
  const [customerId, setCustomerId] = useState("");
  const [customerQuery, setCustomerQuery] = useState("");
  const [fulfillment, setFulfillment] = useState("delivery");
  const [paymentMethod, setPaymentMethod] = useState("cash");
  const [deliveryZoneId, setDeliveryZoneId] = useState("");
  const [vehicleTypeId, setVehicleTypeId] = useState("");
  const [vehiclesCount, setVehiclesCount] = useState(1);
  const [sectionId, setSectionId] = useState("");
  const [productSearch, setProductSearch] = useState("");
  const [items, setItems] = useState([]);

  const customers = useFetch((s) => api.accounts("customer", { status: "approved" }, s), []);
  const zones = useFetch((s) => api.deliveryZones(s).catch(() => []), []);
  const vehicleTypes = useFetch((s) => api.vehicleTypes(s).catch(() => []), []);
  const products = useFetch(
    (s) => (sectionId ? api.products({ sectionId }, s) : Promise.resolve([])),
    [sectionId]
  );

  const customer = (customers.data ?? []).find((c) => c.id === customerId);
  const allowedSections = customer ? (customer.sections || []).filter((s) => s.enabled) : [];

  const filteredCustomers = (customers.data ?? []).filter((c) =>
    !customerQuery.trim() || c.business_name.includes(customerQuery.trim()) || (c.phone || "").includes(customerQuery.trim())
  );
  const filteredProducts = (products.data ?? []).filter((p) =>
    !productSearch.trim() || p.name.includes(productSearch.trim())
  );

  function addItem(p) {
    setItems((prev) => {
      const existing = prev.find((i) => i.productId === p.id);
      if (existing) return prev.map((i) => (i.productId === p.id ? { ...i, qty: i.qty + 1 } : i));
      return [...prev, { productId: p.id, name: p.name, unit: p.unit, price: Number(p.base_price), qty: 1 }];
    });
  }
  function updateQty(productId, qty) {
    setItems((prev) => prev.map((i) => (i.productId === productId ? { ...i, qty: Math.max(1, qty) } : i)));
  }
  function removeItem(productId) {
    setItems((prev) => prev.filter((i) => i.productId !== productId));
  }

  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);

  const create = useAction(() => api.adminCreateOrder({
    customerId,
    fulfillment,
    paymentMethod,
    deliveryZoneId: fulfillment === "delivery" ? (deliveryZoneId || undefined) : undefined,
    vehicleTypeId: fulfillment === "delivery" ? (vehicleTypeId || undefined) : undefined,
    vehiclesCount: fulfillment === "delivery" ? Number(vehiclesCount) : undefined,
    items: items.map((i) => ({ productId: i.productId, qty: i.qty })),
  }));

  const canSubmit = customerId && items.length > 0 && (fulfillment !== "delivery" || deliveryZoneId);

  function resetForm() {
    setCustomerId(""); setItems([]); setSectionId(""); setDeliveryZoneId(""); setVehicleTypeId("");
  }

  return (
    <div className="screen">
      <div className="detail-card add-account-form">
        <h2 className="subsection-heading">إنشاء طلبية جديدة لعميل</h2>

        <label className="field-label">العميل</label>
        <SearchBar value={customerQuery} onChange={setCustomerQuery} placeholder="ابحث بالاسم أو رقم الهاتف..." />
        <select className="field-input" value={customerId}
          onChange={(e) => { setCustomerId(e.target.value); setItems([]); setSectionId(""); }}>
          <option value="">— اختر العميل —</option>
          {filteredCustomers.map((c) => (
            <option key={c.id} value={c.id}>{c.business_name} — {c.phone}</option>
          ))}
        </select>

        {customer && (
          <>
            <label className="field-label">طريقة التسليم</label>
            <div className="tile-row-inline" style={{ marginBottom: 12 }}>
              <button className={"chip" + (fulfillment === "delivery" ? " chip-active" : "")}
                onClick={() => setFulfillment("delivery")}>توصيل</button>
              <button className={"chip" + (fulfillment === "pickup" ? " chip-active" : "")}
                onClick={() => setFulfillment("pickup")}>استلام شخصي</button>
            </div>

            {fulfillment === "delivery" && (
              <>
                <label className="field-label">منطقة التوصيل</label>
                <select className="field-input" value={deliveryZoneId} onChange={(e) => setDeliveryZoneId(e.target.value)}>
                  <option value="">— اختر المنطقة —</option>
                  {(zones.data ?? []).map((z) => <option key={z.id} value={z.id}>{z.name}</option>)}
                </select>
                <label className="field-label">نوع السيارة (اختياري)</label>
                <select className="field-input" value={vehicleTypeId} onChange={(e) => setVehicleTypeId(e.target.value)}>
                  <option value="">— بدون تحديد —</option>
                  {(vehicleTypes.data ?? []).map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}
                </select>
              </>
            )}

            <label className="field-label">طريقة الدفع</label>
            <select className="field-input" value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}>
              {Object.entries(PAYMENT_LABELS).map(([k, l]) => <option key={k} value={k}>{l}</option>)}
            </select>

            <label className="field-label">الأقسام المسموح بها لهذا العميل</label>
            <div className="section-chip-row" style={{ marginBottom: 12 }}>
              {allowedSections.map((s) => (
                <button key={s.id} className={"chip" + (sectionId === s.id ? " chip-active" : "")}
                  onClick={() => setSectionId(s.id)}>{s.name}</button>
              ))}
              {!allowedSections.length && <p className="hint">هذا العميل ليس له أقسام مفعّلة.</p>}
            </div>

            {sectionId && (
              <>
                <SearchBar value={productSearch} onChange={setProductSearch} placeholder="ابحث عن صنف..." />
                {products.loading ? <Spinner /> : (
                  <table className="data-table" style={{ marginBottom: 16 }}>
                    <thead><tr><th>الصنف</th><th>السعر التقديري</th><th></th></tr></thead>
                    <tbody>
                      {filteredProducts.map((p) => (
                        <tr className="data-row" key={p.id} onClick={() => addItem(p)}>
                          <td>{p.name}</td>
                          <td className="cell-muted">{money(p.base_price)} / {p.unit}</td>
                          <td><button className="invoice-action-btn"
                            onClick={(e) => { e.stopPropagation(); addItem(p); }}>إضافة</button></td>
                        </tr>
                      ))}
                      {!filteredProducts.length && (
                        <tr><td colSpan={3} className="cell-muted">لا توجد أصناف مطابقة</td></tr>
                      )}
                    </tbody>
                  </table>
                )}
              </>
            )}

            {items.length > 0 && (
              <>
                <h2 className="subsection-heading">الأصناف المضافة</h2>
                <table className="data-table" style={{ marginBottom: 10 }}>
                  <thead><tr><th>الصنف</th><th>السعر</th><th>الكمية</th><th>الإجمالي</th><th></th></tr></thead>
                  <tbody>
                    {items.map((i) => (
                      <tr key={i.productId}>
                        <td>{i.name}</td>
                        <td className="cell-muted">{money(i.price)}</td>
                        <td>
                          <input className="qty-input" type="number" min="1" value={i.qty} style={{ width: 70 }}
                            onChange={(e) => updateQty(i.productId, Number(e.target.value))} />
                        </td>
                        <td className="cell-amount">{money(i.price * i.qty)}</td>
                        <td><button className="invoice-action-btn" onClick={() => removeItem(i.productId)}>حذف</button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                <p className="hint">السعر النهائي في الفاتورة يُحتسب تلقائيًا وقد يختلف حسب الأسعار الخاصة المتفق عليها مع العميل.</p>
                <div className="summary-block">
                  <div className="summary-row summary-total"><span>إجمالي الأصناف (تقديري)</span><b>{money(subtotal)}</b></div>
                </div>
              </>
            )}
          </>
        )}

        {create.error && <p className="field-error">{create.error}</p>}
        <div className="add-form-actions">
          <button className="btn-primary" disabled={!canSubmit || create.pending}
            onClick={() => create.run().then((order) => { resetForm(); onCreated(order); }).catch(() => {})}>
            {create.pending ? "جارٍ الإنشاء…" : "إنشاء الطلبية وإرسالها للمراجعة"}
          </button>
        </div>
      </div>
    </div>
  );
}

