function EmployeePermissionsForm({ employee, onClose }) {
  const { data, loading, error, reload } = useFetch((s) => api.employeePermissions(employee.id, s), [employee.id]);
  const [pending, setPending] = useState({}); // { [code]: true|false|null } — تعديلات لسا ما اتحفظتش
  const save = useAction((overrides) => api.updateEmployeePermissions(employee.id, { overrides }));

  if (loading) return <div className="detail-card voucher-form"><Spinner /></div>;
  if (error) return <div className="detail-card voucher-form"><ErrorState message={error} onRetry={reload} /></div>;
  if (!data) return null;

  const effective = (code) => {
    if (Object.prototype.hasOwnProperty.call(pending, code)) return pending[code];
    if (Object.prototype.hasOwnProperty.call(data.overrides, code)) return data.overrides[code];
    return null; // بدون استثناء — يعتمد على وضع دوره
  };

  function cycle(code, roleHasIt) {
    const current = effective(code);
    // دورة الحالات: بدون استثناء → عكس وضع الدور → إلغاء العكس (رجوع لبدون استثناء)
    const next = current === null ? !roleHasIt : null;
    setPending((p) => ({ ...p, [code]: next }));
  }

  const dirty = Object.keys(pending).length > 0;

  function submit() {
    const overrides = Object.entries(pending).map(([permissionCode, granted]) => ({ permissionCode, granted }));
    save.run(overrides).then(() => { setPending({}); reload(); }).catch(() => {});
  }

  return (
    <div className="detail-card voucher-form">
      <h2 className="subsection-heading">الصلاحيات الفردية — {employee.name}</h2>
      <p className="hint">
        هذه استثناءات فوق صلاحيات وظيفته ({data.employee.role_name}). اضغط على أي صلاحية لتبديل حالتها:
        منح إضافي، سحب، أو الرجوع لوضع الدور الافتراضي.
      </p>

      <div className="ledger-list" style={{ marginTop: 10, marginBottom: 14 }}>
        {data.permissions.map((p) => {
          const roleHasIt = data.roleGrantedCodes.includes(p.code);
          const state = effective(p.code);
          const label = state === true ? "ممنوحة إضافيًا لهذا الموظف"
            : state === false ? "مسحوبة من هذا الموظف"
            : roleHasIt ? "ممنوحة عبر دوره" : "غير ممنوحة (خارج دوره)";
          const tone = state === true ? "status-pill-approved"
            : state === false ? "status-pill-cancelled"
            : roleHasIt ? "status-pill-approved" : "";
          return (
            <div className="ledger-row" key={p.code} style={{ cursor: "pointer" }}
              onClick={() => cycle(p.code, roleHasIt)}>
              <span className="cell-id">{p.description || p.code}</span>
              <span className={"status-pill " + tone}>{label}</span>
            </div>
          );
        })}
      </div>

      {save.error && <p className="field-error">{save.error}</p>}
      <div className="add-form-actions">
        <button className="btn-primary" disabled={!dirty || save.pending} onClick={submit}>
          {save.pending ? "جارٍ الحفظ…" : "حفظ التعديلات"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إغلاق</button>
      </div>
    </div>
  );
}

function ToggleEmployeeButton({ employee, onDone }) {
  const [confirming, setConfirming] = useState(false);
  const isInactive = employee.is_active === false;

  const deactivate = useAction(() => api.deleteEmployee(employee.id));
  const reactivate = useAction(() => api.updateEmployee(employee.id, { isActive: true }));

  if (isInactive) {
    return (
      <div className="decide-row">
        <button className="invoice-action-btn" disabled={reactivate.pending}
          onClick={() => reactivate.run().then(onDone).catch(() => {})}>
          {reactivate.pending ? "جارٍ التفعيل…" : "إعادة تفعيل"}
        </button>
        {reactivate.error && <span className="field-error" style={{ margin: 0 }}>{reactivate.error}</span>}
      </div>
    );
  }

  if (confirming) {
    return (
      <div className="decide-row">
        <span className="cell-muted" style={{ alignSelf: "center" }}>متأكد؟</span>
        <button className="invoice-action-btn" disabled={deactivate.pending}
          onClick={() => deactivate.run().then(onDone).catch(() => {})}>
          {deactivate.pending ? "جارٍ التعطيل…" : "نعم، عطّل"}
        </button>
        <button className="invoice-action-btn" onClick={() => setConfirming(false)}>تراجع</button>
        {deactivate.error && <span className="field-error" style={{ margin: 0 }}>{deactivate.error}</span>}
      </div>
    );
  }
  return (
    <button className="invoice-action-btn" onClick={() => setConfirming(true)}>
      تعطيل الموظف
    </button>
  );
}

