const FEEDBACK_STATUS_LABELS = { open: "مفتوحة", in_progress: "قيد المتابعة", resolved: "تم الحل", closed: "مغلقة" };
const RESOLUTION_LABELS = { replacement: "استبدال", discount: "خصم", credit_note: "رصيد دائن", no_action: "بدون إجراء" };

function FeedbackPanel() {
  const { data, loading, error, reload } = useFetch(() => api.feedbackList(), []);
  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;
  if (!data?.length) return <Empty icon={Star} text="لا توجد تقييمات أو شكاوى بعد" />;

  return (
    <div className="ledger-list">
      {data.map((f) => <FeedbackRow key={f.id} item={f} onDone={reload} />)}
    </div>
  );
}

function FeedbackRow({ item, onDone }) {
  const [resolving, setResolving] = useState(false);
  const [type, setType] = useState("discount");
  const [amount, setAmount] = useState("");
  const resolve = useAction(() => api.resolveFeedback(item.id, {
    resolutionType: type, resolutionAmount: amount ? Number(amount) : undefined,
  }));

  return (
    <div className="order-row" style={{ cursor: "default" }}>
      <div className="order-row-top">
        <span className="order-row-id">{item.order_number} {item.rating ? `— ${"★".repeat(item.rating)}` : ""}</span>
        <span className={"status-pill" + (item.resolution_status === "resolved" ? " status-pill-approved" : "")}>
          {FEEDBACK_STATUS_LABELS[item.resolution_status]}
        </span>
      </div>
      <span className="order-row-meta">
        {item.customer_name} {item.supplier_name ? `· ${item.supplier_name}` : ""} · {day(item.created_at)}
      </span>
      {item.comment && <p className="hint" style={{ margin: "6px 0" }}>{item.comment}</p>}
      {item.resolution_status === "resolved" ? (
        <span className="cell-muted">تمت المعالجة: {RESOLUTION_LABELS[item.resolution_type]}{item.resolution_amount ? ` — ${money(item.resolution_amount)}` : ""}</span>
      ) : resolving ? (
        <div style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 8, flexWrap: "wrap" }}>
          <select className="field-input" style={{ marginBottom: 0, width: 160 }} value={type} onChange={(e) => setType(e.target.value)}>
            {Object.entries(RESOLUTION_LABELS).map(([k, l]) => <option key={k} value={k}>{l}</option>)}
          </select>
          <input className="field-input" style={{ marginBottom: 0, width: 120 }} type="number" min="0" placeholder="مبلغ (اختياري)"
            value={amount} onChange={(e) => setAmount(e.target.value)} />
          <button className="invoice-action-btn" disabled={resolve.pending}
            onClick={() => resolve.run().then(() => { onDone(); setResolving(false); }).catch(() => {})}>
            <Check size={13} /> تأكيد
          </button>
          <button className="invoice-action-btn" onClick={() => setResolving(false)}>إلغاء</button>
        </div>
      ) : (
        <button className="invoice-action-btn" style={{ marginTop: 8 }} onClick={() => setResolving(true)}>معالجة</button>
      )}
    </div>
  );
}

const RETURN_STATUS_LABELS = { requested: "مطلوب", approved: "معتمد", rejected: "مرفوض", received: "تم الاستلام", refunded: "تم الاسترجاع" };

function ReturnsPanel() {
  const { data, loading, error, reload } = useFetch(() => api.returns(), []);
  const setStatus = useAction((id, body) => api.setReturnStatus(id, body));

  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;
  if (!data?.length) return <Empty icon={RotateCcw} text="لا توجد طلبات إرجاع بعد" />;

  return (
    <table className="data-table">
      <thead><tr><th>رقم الإرجاع</th><th>الفاتورة</th><th>العميل</th><th>السبب</th><th>القيمة</th><th>الحالة</th><th></th></tr></thead>
      <tbody>
        {data.map((r) => (
          <tr key={r.id}>
            <td className="cell-id">{r.return_number}</td>
            <td className="cell-muted">{r.order_number}</td>
            <td>{r.customer_name}</td>
            <td className="cell-muted">{r.reason}</td>
            <td className="cell-amount">{money(r.total)}</td>
            <td><span className={"status-pill" + (r.status === "refunded" ? " status-pill-approved" : r.status === "rejected" ? " status-pill-cancelled" : "")}>
              {RETURN_STATUS_LABELS[r.status]}</span></td>
            <td>
              {r.status === "requested" && (
                <div className="decide-row">
                  <button className="invoice-action-btn" disabled={setStatus.pending}
                    onClick={() => setStatus.run(r.id, { status: "approved" }).then(reload).catch(() => {})}><Check size={13} /> اعتماد</button>
                  <button className="invoice-action-btn" disabled={setStatus.pending}
                    onClick={() => setStatus.run(r.id, { status: "rejected" }).then(reload).catch(() => {})}><X size={13} /> رفض</button>
                </div>
              )}
              {r.status === "approved" && (
                <button className="invoice-action-btn" disabled={setStatus.pending}
                  onClick={() => setStatus.run(r.id, { status: "received" }).then(reload).catch(() => {})}>تأكيد الاستلام</button>
              )}
              {r.status === "received" && (
                <button className="invoice-action-btn" disabled={setStatus.pending}
                  onClick={() => setStatus.run(r.id, { status: "refunded", refundMethod: "cash" }).then(reload).catch(() => {})}>تأكيد الاسترجاع</button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

