function ProfitReport() {
  const [preset, setPreset] = useState("month"); // today | month | year | custom
  const [customFrom, setCustomFrom] = useState("");
  const [customTo, setCustomTo] = useState("");

  const today = new Date();
  const iso = (d) => d.toISOString().slice(0, 10);
  let from, to, groupBy;
  if (preset === "today") {
    from = to = iso(today); groupBy = "day";
  } else if (preset === "month") {
    from = iso(new Date(today.getFullYear(), today.getMonth(), 1));
    to = iso(today); groupBy = "day";
  } else if (preset === "year") {
    from = iso(new Date(today.getFullYear(), 0, 1));
    to = iso(today); groupBy = "month";
  } else {
    from = customFrom || undefined; to = customTo || undefined; groupBy = "day";
  }

  const { data, loading, error, reload } = useFetch(
    (s) => api.profitReport({ from, to, groupBy }, s), [preset, from, to, groupBy]
  );

  const BUCKET_FMT = { day: (d) => day(d), month: (d) => new Date(d).toLocaleDateString("ar", { year: "numeric", month: "long" }) };

  return (
    <>
      <div className="chip-row" style={{ marginBottom: 14 }}>
        <button className={"chip" + (preset === "today" ? " chip-active" : "")} onClick={() => setPreset("today")}>اليوم</button>
        <button className={"chip" + (preset === "month" ? " chip-active" : "")} onClick={() => setPreset("month")}>هذا الشهر</button>
        <button className={"chip" + (preset === "year" ? " chip-active" : "")} onClick={() => setPreset("year")}>هذه السنة</button>
        <button className={"chip" + (preset === "custom" ? " chip-active" : "")} onClick={() => setPreset("custom")}>مخصّص</button>
      </div>

      {preset === "custom" && (
        <div style={{ display: "flex", gap: 10, marginBottom: 14, flexWrap: "wrap" }}>
          <div>
            <label className="field-label">من تاريخ</label>
            <input type="date" className="field-input" value={customFrom} onChange={(e) => setCustomFrom(e.target.value)} />
          </div>
          <div>
            <label className="field-label">إلى تاريخ</label>
            <input type="date" className="field-input" value={customTo} onChange={(e) => setCustomTo(e.target.value)} />
          </div>
        </div>
      )}

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : data && (
        <>
          <div className="stat-grid">
            <div className="stat-tile">
              <span>عمولة جملة المحصّلة</span><b>{money(data.totalCommission)}</b>
            </div>
            <div className="stat-tile">
              <span>المصروفات</span><b>{money(data.totalExpenses)}</b>
            </div>
            <div className="stat-tile">
              <span>صافي الربح</span>
              <b className={data.netProfit >= 0 ? "" : "cell-debt"}>{money(data.netProfit)}</b>
            </div>
          </div>

          <h2 className="subsection-heading">التفصيل حسب الفترة</h2>
          {!data.series.length ? <Empty icon={BarChart2} text="لا توجد بيانات في هذه الفترة" /> : (
            <table className="data-table">
              <thead><tr><th>الفترة</th><th>العمولة</th><th>المصروفات</th><th>الصافي</th></tr></thead>
              <tbody>
                {data.series.map((r) => (
                  <tr key={r.bucket}>
                    <td className="cell-muted">{(BUCKET_FMT[groupBy] || day)(r.bucket)}</td>
                    <td className="cell-amount">{money(r.commission)}</td>
                    <td className="cell-muted">{money(r.expenses)}</td>
                    <td className={r.netProfit >= 0 ? "cell-amount" : "cell-amount cell-debt"}>{money(r.netProfit)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </>
      )}
    </>
  );
}

