function StockVouchersForSupplier({ supplierId }) {
  const [typeFilter, setTypeFilter] = useState("");
  const [creating, setCreating] = useState(null);
  const [showImport, setShowImport] = useState(false);
  const [openId, setOpenId] = useState(null);
  const products = useFetch((s) => api.products({ supplierId }, s), [supplierId]);
  const sections = useFetch((s) => api.sections(s), []);
  const { data, loading, error, reload } = useFetch(
    (s) => api.stockVouchers({ supplierId, voucherType: typeFilter || undefined }, s), [supplierId, typeFilter]
  );

  const TYPE_LABELS = { addition: "إضافة", discount: "خصم" };

  if (openId) return <AdminStockVoucherDetail voucherId={openId} onClose={() => setOpenId(null)} />;

  if (creating) {
    return (
      <AdminStockVoucherForm supplierId={supplierId} voucherType={creating} products={products.data ?? []}
        onClose={() => setCreating(null)}
        onSaved={() => { setCreating(null); reload(); products.reload(); }} />
    );
  }

  if (showImport) {
    return (
      <AdminImportProductsView supplierId={supplierId} sections={sections.data ?? []}
        onClose={() => setShowImport(false)}
        onImported={() => { setShowImport(false); reload(); products.reload(); }} />
    );
  }

  return (
    <div style={{ marginTop: 16 }}>
      <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
        <button className="btn-primary" style={{ marginBottom: 0 }} onClick={() => setCreating("addition")}>
          <Plus size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> فاتورة إضافة
        </button>
        <button className="btn-ghost" style={{ marginBottom: 0 }} onClick={() => setCreating("discount")}>
          − فاتورة خصم
        </button>
        <button className="btn-ghost" style={{ marginBottom: 0 }} onClick={() => setShowImport(true)}>
          استيراد من إكسل
        </button>
      </div>

      <div className="chip-row" style={{ marginBottom: 12 }}>
        <button className={"chip" + (typeFilter === "" ? " chip-active" : "")} onClick={() => setTypeFilter("")}>الكل</button>
        <button className={"chip" + (typeFilter === "addition" ? " chip-active" : "")} onClick={() => setTypeFilter("addition")}>إضافة</button>
        <button className={"chip" + (typeFilter === "discount" ? " chip-active" : "")} onClick={() => setTypeFilter("discount")}>خصم</button>
      </div>

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !data?.length ? <Empty icon={Package} text="لا توجد فواتير مخزون لهذا المورد بعد" />
       : (
        <table className="data-table">
          <thead><tr><th>رقم الفاتورة</th><th>النوع</th><th>عدد الأصناف</th><th>السبب</th><th>التاريخ</th></tr></thead>
          <tbody>
            {data.map((v) => (
              <tr className="data-row" key={v.id} onClick={() => setOpenId(v.id)}>
                <td className="cell-id">{v.voucher_number}</td>
                <td className={v.voucher_type === "addition" ? "cell-amount" : "cell-amount cell-debt"}>
                  {TYPE_LABELS[v.voucher_type]}
                </td>
                <td className="cell-muted">{v.items_count}</td>
                <td className="cell-muted">{v.reason}</td>
                <td className="cell-muted">{day(v.created_at)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

function AdminStockVoucherForm({ supplierId, voucherType, products, onClose, onSaved }) {
  const [query, setQuery] = useState("");
  const [cart, setCart] = useState([]);
  const [reason, setReason] = useState("");
  const isIn = voucherType === "addition";

  const submit = useAction(() => api.createStockVoucher({
    voucherType, supplierId, reason: reason.trim(),
    items: cart.map((c) => ({ productId: c.productId, qty: Number(c.qty) })),
  }));

  const q = query.trim();
  const results = q
    ? products.filter((p) => !cart.some((c) => c.productId === p.id)
        && (p.name.includes(q) || (p.supplier_sku && p.supplier_sku.includes(q))))
      .slice(0, 8)
    : [];

  function addToCart(p) {
    setCart((c) => [...c, { productId: p.id, name: p.name, unit: p.unit, stockQty: p.stock_qty, qty: 1 }]);
    setQuery("");
  }
  function setQty(productId, qty) {
    setCart((c) => c.map((x) => x.productId === productId ? { ...x, qty } : x));
  }
  function removeFromCart(productId) {
    setCart((c) => c.filter((x) => x.productId !== productId));
  }

  const valid = cart.length > 0 && cart.every((c) => Number(c.qty) > 0) && reason.trim().length >= 2;

  return (
    <div style={{ marginTop: 16 }}>
      <button className="link-btn" onClick={onClose} style={{ marginBottom: 12 }}>‹ رجوع للقائمة</button>
      <h2 className="subsection-heading">{isIn ? "فاتورة إضافة جديدة" : "فاتورة خصم جديدة"}</h2>

      <label className="field-label">ابحث عن صنف بالاسم أو رقم الصنف عند المورد</label>
      <input className="field-input" style={{ maxWidth: 400 }} placeholder="اكتب للبحث..."
        value={query} onChange={(e) => setQuery(e.target.value)} />
      {results.length > 0 && (
        <table className="data-table" style={{ marginTop: 8, maxWidth: 560 }}>
          <tbody>
            {results.map((p) => (
              <tr className="data-row" key={p.id} onClick={() => addToCart(p)}>
                <td className="cell-id">{p.name}</td>
                <td className="cell-muted">{p.unit} {p.supplier_sku ? `· #${p.supplier_sku}` : ""}</td>
                <td className="cell-muted">الحالية: {p.stock_qty}</td>
                <td><Plus size={16} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {cart.length > 0 && (
        <table className="data-table" style={{ marginTop: 16, maxWidth: 560 }}>
          <thead><tr><th>الصنف</th><th>الكمية الحالية</th><th>{isIn ? "المضافة" : "المخصومة"}</th><th></th></tr></thead>
          <tbody>
            {cart.map((c) => (
              <tr key={c.productId}>
                <td className="cell-id">{c.name} <span className="cell-muted">({c.unit})</span></td>
                <td className="cell-muted">{c.stockQty}</td>
                <td>
                  <input type="number" min="1" className="qty-input" value={c.qty}
                    onChange={(e) => setQty(c.productId, Math.max(1, Number(e.target.value) || 1))} />
                </td>
                <td><button className="link-btn" onClick={() => removeFromCart(c.productId)}>حذف</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <label className="field-label" style={{ marginTop: 16 }}>سبب الفاتورة</label>
      <input className="field-input" style={{ maxWidth: 400 }}
        placeholder={isIn ? "مثال: توريد جديد" : "مثال: تالف / جرد"}
        value={reason} onChange={(e) => setReason(e.target.value)} />

      {submit.error && <p className="field-error">{submit.error}</p>}

      <div style={{ marginTop: 14 }}>
        <button className="btn-primary" disabled={!valid || submit.pending}
          onClick={() => submit.run().then(onSaved).catch(() => {})}>
          {submit.pending ? "جارٍ الحفظ…" : isIn ? "تأكيد فاتورة الإضافة" : "تأكيد فاتورة الخصم"}
        </button>
      </div>
    </div>
  );
}

function AdminStockVoucherDetail({ voucherId, onClose }) {
  const { data, loading, error } = useFetch(() => api.stockVoucher(voucherId), [voucherId]);

  function printPdf() {
    if (!data) return;
    const w = window.open("", "_blank");
    w.document.write(buildStockVoucherPdfHTML(data));
    w.document.close();
  }

  return (
    <div style={{ marginTop: 16 }}>
      <button className="link-btn" onClick={onClose} style={{ marginBottom: 12 }}>‹ رجوع للقائمة</button>
      {loading ? <Spinner /> : error ? <p className="field-error">{error}</p> : data && (
        <>
          <div className="detail-card" style={{ marginBottom: 16 }}>
            <span className="order-row-id">{data.voucher.voucher_number}</span>
            <p className="order-row-meta">
              {data.voucher.voucher_type === "addition" ? "فاتورة إضافة" : "فاتورة خصم"} ·
              {" "}{data.voucher.supplier_name} · {data.voucher.reason} · {day(data.voucher.created_at)}
            </p>
          </div>
          <table className="data-table">
            <thead><tr><th>الصنف</th><th>الوحدة</th><th>رقم الصنف</th><th>الكمية</th></tr></thead>
            <tbody>
              {data.lines.map((l) => (
                <tr key={l.id}>
                  <td className="cell-id">{l.product_name}</td>
                  <td className="cell-muted">{l.unit}</td>
                  <td className="cell-muted">{l.supplier_sku || "—"}</td>
                  <td className={Number(l.change_qty) >= 0 ? "cell-amount" : "cell-amount cell-debt"}>
                    {Number(l.change_qty) >= 0 ? "+" : ""}{l.change_qty}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <button className="btn-primary" style={{ marginTop: 16 }} onClick={printPdf}>
            🖨️ طباعة / حفظ PDF
          </button>
        </>
      )}
    </div>
  );
}

function buildStockVoucherPdfHTML(data) {
  const { voucher, lines } = data;
  const rows = lines.map((l, n) => `<tr><td>${n + 1}</td><td>${l.product_name}${l.supplier_sku ? ` <span class="sku">#${l.supplier_sku}</span>` : ""}</td>
    <td>${l.unit}</td><td>${Number(l.change_qty) >= 0 ? "+" : ""}${l.change_qty}</td></tr>`).join("");
  const title = voucher.voucher_type === "addition" ? "فاتورة إضافة مخزون" : "فاتورة خصم مخزون";

  return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"/>
<title>${title} — ${voucher.voucher_number}</title><style>
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@700;800&family=Tajawal:wght@400;500;700&display=swap');
*{box-sizing:border-box}body{font-family:'Tajawal',sans-serif;color:#181d2a;margin:0;padding:32px;background:#f4f5f9}
.sheet{max-width:780px;margin:0 auto;background:#fff;border-radius:20px;padding:32px;
  box-shadow:0 1px 3px rgba(24,29,42,.06),0 1px 2px rgba(24,29,42,.04)}
header{display:flex;justify-content:space-between;border-bottom:2px solid #ecedf2;padding-bottom:16px;margin-bottom:20px}
.brand{font-family:'Cairo',sans-serif;font-weight:800;font-size:26px;color:#ff6a1a;margin:0}
.doc-title{font-family:'Cairo',sans-serif;font-weight:800;font-size:18px;text-align:left;margin:0}
.doc-meta{font-size:12.5px;color:#6b7280;text-align:left;margin-top:6px;line-height:1.8}
.sku{font-size:11px;color:#6b7280}
table{width:100%;border-collapse:separate;border-spacing:0;margin-bottom:18px;border-radius:14px;overflow:hidden;
  box-shadow:0 1px 3px rgba(24,29,42,.06)}
thead th{background:#181d2a;color:#fff;padding:10px;font-size:12.5px;text-align:right;font-family:'Cairo',sans-serif;font-weight:700}
tbody td{border-bottom:1px solid #ecedf2;padding:10px;font-size:13px;background:#fff}
tbody tr:last-child td{border-bottom:none}
tbody td:first-child{width:40px;text-align:center;color:#6b7280}
.pdf-toolbar{position:sticky;top:0;z-index:10;display:flex;gap:10px;justify-content:center;
  background:#181d2a;padding:12px;margin-bottom:20px;border-radius:14px}
.pdf-toolbar button{background:#ff6a1a;color:#fff;border:none;padding:10px 20px;font-family:'Cairo',sans-serif;
  font-weight:700;font-size:13px;cursor:pointer;border-radius:999px}
.pdf-toolbar button:last-child{background:rgba(255,255,255,.15)}
@media print{.pdf-toolbar{display:none}body{background:#fff;padding:0}.sheet{box-shadow:none;border-radius:0}}
</style></head><body>
<div class="pdf-toolbar">
  <button onclick="window.print()">🖨️ طباعة / حفظ PDF</button>
  <button onclick="window.close()">✕ إغلاق</button>
</div>
<div class="sheet">
<header><p class="brand">جملة</p>
<div><h2 class="doc-title">${title}</h2><div class="doc-meta">
المورد: ${voucher.supplier_name}<br/>
رقم الفاتورة: <strong style="color:#181d2a">${voucher.voucher_number}</strong><br/>التاريخ: ${new Date(voucher.created_at).toLocaleString("ar")}<br/>
السبب: ${voucher.reason || "—"}</div></div></header>
<table><thead><tr><th>#</th><th>الصنف</th><th>الوحدة</th><th>الكمية</th></tr></thead>
<tbody>${rows}</tbody></table>
</div></body></html>`;
}

// استيراد إكسل نيابة عن مورد معيّن — نفس آلية استيراد المورد بالظبط
function AdminImportProductsView({ supplierId, sections, onClose, onImported }) {
  const [rows, setRows] = useState(null);
  const [fileName, setFileName] = useState("");
  const [result, setResult] = useState(null);
  const [confirmDrafts, setConfirmDrafts] = useState([]);

  const parse = useAction((file) => new Promise((resolve, reject) => {
    import("xlsx").then((XLSX) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const wb = XLSX.read(e.target.result, { type: "array" });
          const sheet = wb.Sheets["الأصناف"] || wb.Sheets[wb.SheetNames[0]];
          const json = XLSX.utils.sheet_to_json(sheet, { defval: "" });
          const cleaned = json
            .filter((r) => String(r["اسم الصنف"] || "").trim())
            .map((r) => ({
              sectionName: String(r["القسم"] || "").trim(),
              name: String(r["اسم الصنف"] || "").trim(),
              unit: String(r["وحدة البيع"] || "").trim(),
              basePrice: Number(r["السعر (د.ل)"] || 0),
              stockQty: Number(r["الكمية المتوفرة"] || 0),
              supplierSku: String(r["رقم الصنف عندك (اختياري)"] || "").trim(),
            }));
          resolve(cleaned);
        } catch (err) { reject("تعذّر قراءة الملف — تأكد من استخدام النموذج الصحيح"); }
      };
      reader.readAsArrayBuffer(file);
    });
  }));

  const noSkuRows = rows?.filter((r) => !r.supplierSku) ?? [];
  const withSkuRows = rows?.filter((r) => r.supplierSku) ?? [];

  const submit = useAction(() => api.importProducts(
    withSkuRows.map((r) => ({ ...r, sectionId: sections.find((s) => s.name === r.sectionName)?.id })),
    supplierId
  ));

  const confirmNew = useAction(() => api.confirmNewImports(
    confirmDrafts.filter((r) => r.sectionId), supplierId
  ));

  function handleFirstResult(res) {
    setResult(res);
    setConfirmDrafts(res.needsConfirmation.map((r) => ({
      ...r, sectionId: sections.find((s) => s.name === r.sectionName)?.id || "",
    })));
  }

  if (result) {
    return (
      <div style={{ marginTop: 16 }}>
        <p className="hint" style={{ marginBottom: 12 }}>
          تم تحديث مخزون {result.updatedCount} صنف موجود بالفعل تلقائيًا.
          {result.skippedCount > 0 && ` تم تجاهل ${result.skippedCount} صف (بدون رقم صنف).`}
        </p>

        {result.needsConfirmation.length === 0 ? (
          <>
            <p className="hint">لا توجد أصناف جديدة تحتاج تأكيد — الاستيراد اكتمل.</p>
            <button className="btn-primary" onClick={onImported}>تم</button>
          </>
        ) : (
          <>
            <div className="note-block" style={{ marginBottom: 14, maxWidth: 560 }}>
              <span className="note-label">أصناف جديدة تحتاج مراجعتك</span>
              <p>رقم الصنف لكل صف من دول غير موجود عند هذا المورد. اختر قسمًا وأكّد، أو ألغِ لو الرقم غلط.</p>
            </div>

            {confirmDrafts.map((row, i) => (
              <div key={i} className="supplier-item-row" style={{ padding: "10px 2px", maxWidth: 560 }}>
                <div className="supplier-item-top">
                  <span className="invoice-line-name">{row.name} <i>#{row.supplierSku}</i></span>
                  <span className="invoice-line-price">{money(row.basePrice)}</span>
                </div>
                <span className="supplier-item-qty">الكمية: {row.stockQty} — {row.unit}</span>
                <select className="field-input" style={{ marginTop: 8 }} value={row.sectionId}
                  onChange={(e) => setConfirmDrafts((d) => d.map((x, idx) =>
                    idx === i ? { ...x, sectionId: e.target.value } : x))}>
                  <option value="">اختر القسم لهذا الصنف الجديد</option>
                  {sections.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
            ))}

            {confirmNew.error && <p className="field-error">{confirmNew.error}</p>}
            <button className="btn-primary" style={{ marginTop: 14 }}
              disabled={confirmNew.pending || !confirmDrafts.some((r) => r.sectionId)}
              onClick={() => confirmNew.run().then(onImported).catch(() => {})}>
              {confirmNew.pending ? "جارٍ الحفظ…" : `تأكيد إضافة ${confirmDrafts.filter((r) => r.sectionId).length} صنف جديد`}
            </button>
          </>
        )}
        <div style={{ marginTop: 10 }}><button className="btn-ghost" onClick={onClose}>إغلاق</button></div>
      </div>
    );
  }

  return (
    <div style={{ marginTop: 16 }}>
      <button className="link-btn" onClick={onClose} style={{ marginBottom: 12 }}>‹ رجوع للقائمة</button>
      <label className="field-label">اختر ملف الإكسل (بنفس صيغة النموذج المُعتمد)</label>
      <input type="file" accept=".xlsx" className="field-input" style={{ maxWidth: 400 }}
        onChange={(e) => {
          const f = e.target.files[0]; if (!f) return;
          setFileName(f.name);
          parse.run(f).then(setRows).catch(() => {});
        }} />

      {parse.error && <p className="field-error">{parse.error}</p>}

      {rows && (
        <>
          <p className="hint">تم العثور على {rows.length} صنف في «{fileName}»</p>
          {noSkuRows.length > 0 && (
            <div className="note-block" style={{ marginTop: 8, maxWidth: 560 }}>
              <span className="note-label">تنبيه</span>
              <p>{noSkuRows.length} صف بدون رقم صنف وسيُتجاهل تمامًا: {noSkuRows.map((r) => r.name).join("، ")}</p>
            </div>
          )}
          {submit.error && <p className="field-error">{submit.error}</p>}
          <button className="btn-primary" disabled={submit.pending || !withSkuRows.length}
            onClick={() => submit.run().then(handleFirstResult).catch(() => {})}>
            {submit.pending ? "جارٍ المعالجة…" : `متابعة الاستيراد (${withSkuRows.length} صف)`}
          </button>
        </>
      )}
    </div>
  );
}

function InventoryReport({ onGo }) {
  const [query, setQuery] = useState("");
  const { data, loading, error, reload } = useFetch((s) => api.products(undefined, s), []);
  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;

  const q = query.trim();
  const rows = (data ?? []).filter((p) => !q || p.name.includes(q) || p.supplier_name?.includes(q));
  const totalUnits = rows.reduce((s, p) => s + Number(p.stock_qty), 0);
  const outOfStock = rows.filter((p) => Number(p.stock_qty) <= 0).length;

  return (
    <>
      <div className="stat-grid">
        <Stat label="إجمالي الأصناف" value={rows.length} />
        <Stat label="إجمالي الوحدات بالمخزون" value={totalUnits} />
        <Stat label="أصناف غير متوفرة" value={outOfStock} debt={outOfStock > 0} />
      </div>
      <SearchBar value={query} onChange={setQuery} placeholder="ابحث باسم الصنف أو المورد..." />
      <table className="data-table">
        <thead><tr><th>الصنف</th><th>المورد</th><th>القسم</th><th>الوحدة</th><th>رقم الصنف</th><th>الكمية المتوفرة</th></tr></thead>
        <tbody>
          {rows.map((p) => (
            <tr className="data-row" key={p.id} onClick={() => onGo("itemDetail", { productId: p.id })}>
              <td className="cell-id">{p.name}</td>
              <td className="cell-muted">{p.supplier_name}</td>
              <td className="cell-muted">{p.section_name}</td>
              <td className="cell-muted">{p.unit}</td>
              <td className="cell-muted">{p.supplier_sku || "—"}</td>
              <td className={Number(p.stock_qty) <= 0 ? "cell-amount cell-debt" : "cell-amount"}>{p.stock_qty}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {!rows.length && <Empty icon={Package} text="لا توجد أصناف مطابقة" />}
    </>
  );
}

function OverviewReport() {
  const { data, loading, error, reload } = useFetch((s) => api.orders(undefined, s), []);
  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;

  const list = data ?? [];
  const active = list.filter((o) => o.status !== "cancelled");
  const totalSales = active.reduce((s, o) => s + Number(o.grand_total), 0);
  const byStatus = {};
  list.forEach((o) => { byStatus[o.status] = (byStatus[o.status] || 0) + 1; });

  return (
    <>
      <div className="stat-grid">
        <Stat label="إجمالي المبيعات" value={money(totalSales)} />
        <Stat label="عدد الطلبيات" value={list.length} />
        <Stat label="طلبيات ملغاة" value={list.length - active.length} />
      </div>
      <h2 className="subsection-heading">الطلبيات حسب الحالة</h2>
      <table className="data-table">
        <thead><tr><th>الحالة</th><th>العدد</th></tr></thead>
        <tbody>
          {Object.entries(byStatus).map(([k, v]) => (
            <tr key={k}><td>{statusLabel(k)}</td><td className="cell-amount">{v}</td></tr>
          ))}
        </tbody>
      </table>
    </>
  );
}

function CustomersReport({ onGo }) {
  const [query, setQuery] = useState("");
  const { data, loading, error, reload } = useFetch((s) => api.orders(undefined, s), []);
  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;

  const map = new Map();
  (data ?? []).forEach((o) => {
    if (!map.has(o.customer_id)) {
      map.set(o.customer_id, { id: o.customer_id, name: o.customer_name, count: 0, total: 0, paid: 0, remaining: 0 });
    }
    const m = map.get(o.customer_id);
    m.count += 1;
    if (o.status !== "cancelled") {
      m.total += Number(o.grand_total);
      m.paid += Number(o.paid_amount);
      m.remaining += Math.max(0, Number(o.grand_total) - Number(o.paid_amount));
    }
  });
  const q = query.trim();
  const rows = [...map.values()].filter((r) => !q || r.name.includes(q))
    .sort((a, b) => b.remaining - a.remaining);

  return (
    <>
      <SearchBar value={query} onChange={setQuery} placeholder="ابحث عن عميل..." />
      <table className="data-table">
        <thead><tr><th>العميل</th><th>الطلبيات</th><th>المشتريات</th><th>المدفوع</th><th>المتبقي عليه</th></tr></thead>
        <tbody>
          {rows.map((r) => (
            <tr className="data-row" key={r.id}
              onClick={() => onGo("customerLedger", { accountId: r.id, partyName: r.name })}>
              <td className="cell-id">{r.name}</td>
              <td className="cell-muted">{r.count}</td>
              <td className="cell-muted">{money(r.total)}</td>
              <td className="cell-muted">{money(r.paid)}</td>
              <td className={r.remaining > 0 ? "cell-amount cell-debt" : "cell-amount"}>{money(r.remaining)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {!rows.length && <Empty icon={Users} text="لا يوجد عملاء مطابقون" />}
    </>
  );
}

