function PriceRulesPanel({ productId }) {
  const { data, loading, error, reload } = useFetch(() => api.priceRules(productId), [productId]);
  const [showAdd, setShowAdd] = useState(false);
  const toggle = useAction((id, isActive) => api.togglePriceRule(id, isActive));

  const RULE_LABELS = { customer_special: "سعر خاص لعميل", qty_break: "خصم حسب الكمية", agreement: "بالاتفاق" };

  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;

  return (
    <>
      <button className="chip chip-add" style={{ marginBottom: 16 }} onClick={() => setShowAdd((v) => !v)}>
        <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> قاعدة تسعير جديدة
      </button>
      {showAdd && <PriceRuleForm productId={productId} onClose={() => setShowAdd(false)} onDone={reload} />}

      {!data?.length ? <Empty icon={Package} text="لا توجد قواعد تسعير خاصة لهذا الصنف" /> : (
        <table className="data-table">
          <thead><tr><th>النوع</th><th>العميل</th><th>الحد الأدنى للكمية</th><th>السعر</th><th>الحالة</th><th></th></tr></thead>
          <tbody>
            {data.map((r) => (
              <tr key={r.id}>
                <td className="cell-muted">{RULE_LABELS[r.rule_type] || r.rule_type}</td>
                <td>{r.customer_name || "كل العملاء"}</td>
                <td className="cell-muted">{r.min_qty}</td>
                <td className="cell-amount">{money(r.price)}</td>
                <td><span className={"status-pill" + (r.is_active ? " status-pill-approved" : " status-pill-cancelled")}>
                  {r.is_active ? "مفعّلة" : "موقوفة"}</span></td>
                <td>
                  <button className="invoice-action-btn" disabled={toggle.pending}
                    onClick={() => toggle.run(r.id, !r.is_active).then(reload).catch(() => {})}>
                    {r.is_active ? "إيقاف" : "تفعيل"}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  );
}

function PriceRuleForm({ productId, onClose, onDone }) {
  const [form, setForm] = useState({ ruleType: "qty_break", customerId: "", minQty: "1", price: "" });
  const create = useAction(() => api.createPriceRule(productId, {
    ruleType: form.ruleType,
    customerId: form.ruleType === "customer_special" ? form.customerId.trim() || undefined : undefined,
    minQty: Number(form.minQty), price: Number(form.price),
  }));
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  return (
    <div className="detail-card voucher-form">
      <h2 className="subsection-heading">قاعدة تسعير جديدة</h2>
      <label className="field-label">النوع</label>
      <select className="field-input" value={form.ruleType} onChange={set("ruleType")}>
        <option value="qty_break">خصم حسب الكمية (لكل العملاء)</option>
        <option value="customer_special">سعر خاص لعميل معين</option>
        <option value="agreement">سعر بالاتفاق</option>
      </select>

      {form.ruleType === "customer_special" && (
        <>
          <label className="field-label">معرّف العميل (UUID)</label>
          <input className="field-input" value={form.customerId} onChange={set("customerId")} dir="ltr" />
        </>
      )}

      <label className="field-label">الحد الأدنى للكمية</label>
      <input className="field-input" type="number" min="1" value={form.minQty} onChange={set("minQty")} />

      <label className="field-label">السعر (د.ل)</label>
      <input className="field-input" type="number" min="0" value={form.price} onChange={set("price")} />

      {create.error && <p className="field-error">{create.error}</p>}
      <div className="add-form-actions">
        <button className="btn-primary" disabled={!form.price || create.pending}
          onClick={() => create.run().then(() => { onDone(); onClose(); }).catch(() => {})}>
          {create.pending ? "جارٍ الحفظ…" : "حفظ القاعدة"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

/* --------------------------- الخزينة --------------------------- */

function TreasuryReport() {
  const [sub, setSub] = useState("vouchers");
  const treasuries = useFetch((s) => api.treasuries(s), []);
  const vouchers = useFetch((s) => api.vouchers(undefined, s), []);
  const expenses = useFetch((s) => api.expenses(undefined, s), [], { skip: sub !== "expenses" });
  const drivers = useFetch((s) => api.driversCash(s), [], { skip: sub !== "drivers" });
  const settleDriver = useAction((id) => api.settleDriver(id));
  const [query, setQuery] = useState("");
  const [form, setForm] = useState(null);   // 'receipt' | 'payment' | 'transfer' | 'expense'

  const q = query.trim().toLowerCase();
  const visible = (vouchers.data ?? []).filter(
    (v) => !q || v.party_name.includes(query.trim()) || v.voucher_number.toLowerCase().includes(q)
  );
  const visibleExpenses = (expenses.data ?? []).filter(
    (e) => !q || e.description.includes(query.trim()) || (e.beneficiary || "").includes(query.trim())
      || e.expense_number.toLowerCase().includes(q)
  );

  function refresh() { vouchers.reload(); treasuries.reload(); expenses.reload(); drivers.reload(); }

  return (
    <>
      <div className="stat-grid">
        {(treasuries.data ?? []).map((t) => (
          <Stat key={t.id} label={`رصيد ${t.name}`} value={money(t.balance)} />
        ))}
      </div>

      <div className="toolbar-row">
        <div className="chip-row">
          <button className={"chip" + (sub === "vouchers" ? " chip-active" : "")} onClick={() => setSub("vouchers")}>كل الإيصالات</button>
          <button className={"chip" + (sub === "expenses" ? " chip-active" : "")} onClick={() => setSub("expenses")}>كشف المصروفات</button>
          <button className={"chip" + (sub === "hawala" ? " chip-active" : "")} onClick={() => setSub("hawala")}>خزينة الحوالات</button>
          <button className={"chip" + (sub === "drivers" ? " chip-active" : "")} onClick={() => setSub("drivers")}>تحصيلات المندوبين</button>
          <button className="chip chip-add" onClick={() => setForm(form === "receipt" ? null : "receipt")}>
            <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> إيصال قبض
          </button>
          <button className="chip chip-add" onClick={() => setForm(form === "payment" ? null : "payment")}>
            <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> إيصال دفع
          </button>
          <button className="chip chip-add" onClick={() => setForm(form === "expense" ? null : "expense")}>
            <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> مصروف جديد
          </button>
          <button className="chip chip-add" onClick={() => setForm(form === "transfer" ? null : "transfer")}>
            <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> تحويل بين الخزائن
          </button>
        </div>
        <SearchBar inline value={query} onChange={setQuery} placeholder="ابحث برقم الإيصال أو الاسم..." />
      </div>

      {form === "transfer" ? <TransferForm onClose={() => setForm(null)} onDone={refresh} />
       : form === "expense" ? <ExpenseForm onClose={() => setForm(null)} onDone={refresh} />
       : form && <VoucherForm type={form} onClose={() => setForm(null)} onDone={refresh} />}

      {sub === "drivers" ? (
        drivers.loading ? <Spinner />
         : drivers.error ? <ErrorState message={drivers.error} onRetry={drivers.reload} />
         : !(drivers.data ?? []).length ? <Empty icon={Wallet} text="لا يوجد مندوبون نشطون" />
         : (
          <>
            {settleDriver.error && <p className="field-error">{settleDriver.error}</p>}
            <table className="data-table">
              <thead>
                <tr><th>المندوب</th><th>طلبيات مسندة</th><th>مسلّمة</th><th>كاش محصّل</th>
                  <th>مسلّم للشركة</th><th>المتبقي بحوزته</th><th></th></tr>
              </thead>
              <tbody>
                {drivers.data.map((d) => (
                  <tr key={d.driver_id}>
                    <td className="cell-id">{d.name}</td>
                    <td className="cell-muted">{d.orders_assigned}</td>
                    <td className="cell-muted">{d.orders_delivered}</td>
                    <td className="cell-muted">{money(d.cash_collected)}</td>
                    <td className="cell-muted">{money(d.cash_settled)}</td>
                    <td className={Number(d.cash_in_hand) > 0 ? "cell-amount cell-debt" : "cell-amount"}>
                      {money(d.cash_in_hand)}
                    </td>
                    <td>
                      {Number(d.cash_in_hand) > 0 && (
                        <button className="invoice-action-btn" disabled={settleDriver.pending}
                          onClick={() => settleDriver.run(d.driver_id).then(refresh).catch(() => {})}>
                          <Check size={14} /> استلام النقدية
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )
      ) : sub === "expenses" ? (
        expenses.loading ? <Spinner />
         : expenses.error ? <ErrorState message={expenses.error} onRetry={expenses.reload} />
         : !visibleExpenses.length ? <Empty icon={Wallet} text="لا توجد مصروفات مطابقة" />
         : (
          <table className="data-table">
            <thead>
              <tr><th>رقم المصروف</th><th>التاريخ</th><th>التصنيف</th><th>الوصف</th>
                <th>المستفيد</th><th>الخزينة</th><th>الطريقة</th><th>المبلغ</th></tr>
            </thead>
            <tbody>
              {visibleExpenses.map((e) => (
                <tr key={e.id}>
                  <td className="cell-id">{e.expense_number}</td>
                  <td className="cell-muted">{day(e.expense_date)}</td>
                  <td><span className="status-pill status-pill-amber">{EXPENSE_CATEGORY_LABELS[e.category] || e.category}</span></td>
                  <td>{e.description}</td>
                  <td className="cell-muted">{e.beneficiary || "—"}</td>
                  <td className="cell-muted">{e.treasury_name}</td>
                  <td className="cell-muted">{e.method === "cash" ? "نقدًا" : "حوالة"}</td>
                  <td className="cell-amount cell-debt">{money(e.amount)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )
      ) : vouchers.loading ? <Spinner />
       : vouchers.error ? <ErrorState message={vouchers.error} onRetry={vouchers.reload} />
       : (
        <table className="data-table">
          <thead>
            <tr><th>رقم الإيصال</th><th>التاريخ</th><th>النوع</th><th>الطرف</th><th>الاسم</th>
              <th>الخزينة</th><th>الطريقة</th><th>الحالة</th><th>المبلغ</th><th></th></tr>
          </thead>
          <tbody>
            {(sub === "hawala" ? visible.filter((v) => v.treasury_code === "hawala") : visible).map((v) => (
              <tr key={v.id}>
                <td className="cell-id">{v.voucher_number}</td>
                <td className="cell-muted">{day(v.created_at)}</td>
                <td><span className={"status-pill" + (v.voucher_type === "payment" ? " status-pill-amber" : " status-pill-approved")}>
                  {v.voucher_type === "receipt" ? "إيصال قبض" : "إيصال دفع"}</span></td>
                <td className="cell-muted">
                  {{ customer: "عميل", supplier: "مورد", driver: "مندوب", employee: "موظف" }[v.party_type] || "أخرى"}
                </td>
                <td className="cell-id">{v.party_name}</td>
                <td className="cell-muted">{v.treasury_name}</td>
                <td className="cell-muted">{v.method === "cash" ? "نقدًا" : "حوالة"}</td>
                <td>
                  {v.approval_status === "pending"
                    ? <VoucherDecide id={v.id} onDone={refresh} />
                    : <span className={"status-pill" + (v.approval_status === "approved" ? " status-pill-approved" : " status-pill-cancelled")}>
                        {v.approval_status === "approved" ? "معتمد" : "مرفوض"}</span>}
                </td>
                <td className="cell-amount">{money(v.amount)}</td>
                <td>
                  {v.approval_status === "approved" && (
                    <button className="invoice-action-btn" onClick={() => openVoucherPdf(v.id)}>
                      <Printer size={14} />PDF
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  );
}

function buildVoucherHTML(v) {
  const typeLabel = v.voucher_type === "receipt" ? "سند قبض" : "سند صرف";
  const methodLabel = v.method === "cash" ? "نقدًا" : v.method === "transfer" ? "حوالة مصرفية" : "بطاقة";
  return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@700;800&family=Tajawal:wght@400;500;700&display=swap');
  body{font-family:'Tajawal',sans-serif;padding:0;margin:0;background:#f4f5f9;color:#181d2a}
  .pdf-toolbar{position:sticky;top:0;z-index:10;display:flex;gap:10px;justify-content:center;
    background:#181d2a;padding:14px}
  .pdf-toolbar button{background:#ff6a1a;color:#fff;border:none;padding:10px 20px;
    font-family:'Cairo',sans-serif;font-weight:700;font-size:13px;cursor:pointer;border-radius:999px}
  .pdf-toolbar button:last-child{background:rgba(255,255,255,.15)}
  .sheet{max-width:480px;margin:28px auto;background:#fff;border-radius:20px;padding:28px;
    box-shadow:0 1px 3px rgba(24,29,42,.06),0 1px 2px rgba(24,29,42,.04)}
  .badge{display:inline-block;background:#ff6a1a;color:#fff;font-family:'Cairo',sans-serif;font-weight:700;
    font-size:11.5px;border-radius:999px;padding:5px 14px;margin-bottom:10px}
  h1{font-family:'Cairo',sans-serif;font-size:20px;text-align:center;margin:0 0 4px;color:#181d2a}
  .sub{text-align:center;color:#6b7280;font-size:12px;margin:0 0 20px}
  .row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #ecedf2;font-size:14px}
  .total{font-family:'Cairo',sans-serif;font-weight:800;font-size:18px;color:#fff;
    background:#181d2a;border-radius:14px;margin-top:14px;padding:14px 16px;border-bottom:none}
  .center{display:flex;flex-direction:column;align-items:center}
  @media print{.pdf-toolbar{display:none}body{background:#fff}.sheet{margin:0;box-shadow:none;border-radius:0}}
</style></head><body>
<div class="pdf-toolbar">
  <button onclick="window.print()">🖨️ طباعة / حفظ PDF</button>
  <button onclick="window.close()">✕ إغلاق</button>
</div>
<div class="sheet">
  <div class="center"><span class="badge">جملة</span></div>
  <h1>${typeLabel}</h1>
  <p class="sub">رقم السند: ${v.voucher_number}</p>
  <div class="row"><span>التاريخ</span><span>${String(v.created_at || v.approved_at).slice(0, 10)}</span></div>
  <div class="row"><span>الطرف</span><span>${v.party_name}</span></div>
  <div class="row"><span>طريقة الدفع</span><span>${methodLabel}</span></div>
  ${v.note ? `<div class="row"><span>ملاحظة</span><span>${v.note}</span></div>` : ""}
  <div class="row total"><span>المبلغ</span><span>${Number(v.amount).toFixed(2)} د.ل</span></div>
</div>
</body></html>`;
}

function openVoucherPdf(id) {
  api.voucherData(id).then((v) => {
    const w = window.open("", "_blank");
    if (!w) return alert("يرجى السماح بالنوافذ المنبثقة لعرض الإيصال.");
    w.document.write(buildVoucherHTML(v));
    w.document.close();
  }).catch(() => alert("تعذّر تحميل بيانات الإيصال"));
}

function VoucherDecide({ id, onDone }) {
  const decide = useAction((approve) => api.decideVoucher(id, { approve }));
  return (
    <div className="decide-row">
      <button className="invoice-action-btn" disabled={decide.pending}
        onClick={() => decide.run(true).then(onDone).catch(() => {})}><Check size={13} /> اعتماد</button>
      <button className="invoice-action-btn" disabled={decide.pending}
        onClick={() => decide.run(false).then(onDone).catch(() => {})}><X size={13} /> رفض</button>
    </div>
  );
}

function VoucherForm({ type, onClose, onDone }) {
  const [form, setForm] = useState({
    partyType: type === "receipt" ? "customer" : "supplier",
    partyId: "", partyName: "", amount: "", method: "cash", note: "",
  });
  const [partyQuery, setPartyQuery] = useState("");
  const linkedType = form.partyType === "customer" || form.partyType === "supplier";

  // نبحث بس عن الحسابات المعتمدة (approved) — لا موقوفة ولا بانتظار الاعتماد
  const { data: matches } = useFetch(
    (s) => linkedType && partyQuery.trim()
      ? api.accounts(form.partyType, { status: "approved", search: partyQuery.trim() }, s)
      : Promise.resolve([]),
    [form.partyType, partyQuery]
  );

  const create = useAction(() => api.createVoucher({
    voucherType: type, partyType: form.partyType,
    partyId: linkedType ? (form.partyId || undefined) : undefined,
    partyName: form.partyName.trim(),
    amount: Number(form.amount), method: form.method, note: form.note || undefined,
  }));
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  function selectAccount(acc) {
    setForm((f) => ({ ...f, partyId: acc.id, partyName: acc.business_name }));
    setPartyQuery("");
  }
  function changePartyType(e) {
    setForm((f) => ({ ...f, partyType: e.target.value, partyId: "", partyName: "" }));
    setPartyQuery("");
  }

  // الخزينة محسوبة تلقائيًا ولا تُترك للاختيار: النقدي يدخل خزينة المبيعات (قبض) أو
  // يُخصم من الرئيسية (دفع)، والحوالة (قبض أو دفع) تدخل/تُخصم من خزينة الحوالات دائمًا
  const treasuryLabel = form.method === "transfer"
    ? "خزينة الحوالات"
    : type === "receipt" ? "خزينة المبيعات" : "الخزينة الرئيسية";

  // رصيد الطرف الحالي (كم عليه أو كم له) — يساعد وقت تحديد قيمة الإيصال
  const { data: ledger } = useFetch(
    (s) => linkedType && form.partyId
      ? (form.partyType === "customer" ? api.customerLedger(form.partyId, s) : api.supplierLedger(form.partyId, s))
      : Promise.resolve(null),
    [form.partyType, form.partyId]
  );
  const currentBalance = ledger?.length ? Number(ledger[ledger.length - 1].balance) : null;

  return (
    <div className="detail-card voucher-form">
      <h2 className="subsection-heading">
        {type === "receipt" ? "إيصال قبض جديد" : "إيصال دفع جديد"}
      </h2>

      <label className="field-label">الطرف</label>
      <select className="field-input" value={form.partyType} onChange={changePartyType}>
        <option value="customer">عميل</option>
        <option value="supplier">مورد</option>
        <option value="employee">موظف</option>
        <option value="other">أخرى (مستفيد)</option>
      </select>

      {linkedType ? (
        <>
          <label className="field-label">الاسم — ابحث واختر من الحسابات المعتمدة</label>
          {form.partyId ? (
            <div className="party-selected-chip">
              <span>{form.partyName}</span>
              <button className="link-btn" onClick={() => setForm((f) => ({ ...f, partyId: "", partyName: "" }))}>
                تغيير
              </button>
            </div>
          ) : (
            <>
              <input className="field-input" value={partyQuery} onChange={(e) => setPartyQuery(e.target.value)}
                placeholder="اكتب اسم العميل أو المورد..." />
              {matches?.length > 0 && (
                <div className="ledger-list" style={{ marginTop: 6, marginBottom: 10 }}>
                  {matches.map((acc) => (
                    <div className="ledger-row" key={acc.id} style={{ cursor: "pointer" }}
                      onClick={() => selectAccount(acc)}>
                      <span className="cell-id">{acc.business_name}</span>
                      <span className="cell-muted">{acc.phone}</span>
                    </div>
                  ))}
                </div>
              )}
              {partyQuery.trim() && !matches?.length && (
                <p className="hint">لا توجد حسابات معتمدة مطابقة — تأكد من الاسم أو أن الحساب معتمد وغير موقوف</p>
              )}
            </>
          )}
          {form.partyId && currentBalance !== null && (
            <p className="hint" style={{ fontWeight: 600 }}>
              {currentBalance > 0
                ? `رصيده الحالي: له ${money(currentBalance)}`
                : currentBalance < 0
                ? `رصيده الحالي: عليه ${money(Math.abs(currentBalance))}`
                : "رصيده الحالي: صفر (لا له ولا عليه)"}
            </p>
          )}
        </>
      ) : (
        <>
          <label className="field-label">الاسم</label>
          <input className="field-input" value={form.partyName} onChange={set("partyName")} />
        </>
      )}

      <label className="field-label">المبلغ (د.ل)</label>
      <input className="field-input" type="number" min="0" value={form.amount} onChange={set("amount")} />

      <label className="field-label">الطريقة</label>
      <div className="tile-row-inline">
        {[["cash", "نقدًا"], ["transfer", "حوالة مصرفية"]].map(([v, l]) => (
          <button key={v} className={"chip" + (form.method === v ? " chip-active" : "")}
            onClick={() => setForm((f) => ({ ...f, method: v }))}>{l}</button>
        ))}
      </div>

      <p className="voucher-balance-line">
        {type === "receipt" ? "تدخل" : "تُخصم من"}: <b>{treasuryLabel}</b>
      </p>

      <label className="field-label">ملاحظة</label>
      <input className="field-input" value={form.note} onChange={set("note")} placeholder="اختياري" />

      {form.method === "transfer" && (
        <p className="hint">الحوالة تبقى بانتظار الاعتماد حتى يراجعها موظف الحسابات.</p>
      )}
      {create.error && <p className="field-error">{create.error}</p>}

      <div className="add-form-actions">
        <button className="btn-primary" disabled={create.pending || !form.partyName.trim() || !form.amount}
          onClick={() => create.run().then(() => { onDone(); onClose(); }).catch(() => {})}>
          {create.pending ? "جارٍ الحفظ…" : "حفظ الإيصال"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

function ExpenseForm({ onClose, onDone }) {
  const [form, setForm] = useState({
    category: "other", description: "", beneficiary: "", amount: "", method: "cash",
    expenseDate: new Date().toISOString().slice(0, 10),
  });
  const create = useAction(() => api.createExpense({
    category: form.category, description: form.description.trim(),
    beneficiary: form.beneficiary.trim() || undefined,
    amount: Number(form.amount), method: form.method, expenseDate: form.expenseDate,
  }));
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const treasuryLabel = form.method === "transfer" ? "خزينة الحوالات" : "الخزينة الرئيسية";
  const valid = form.description.trim() && form.amount;

  return (
    <div className="detail-card voucher-form">
      <h2 className="subsection-heading">مصروف جديد</h2>

      <label className="field-label">التصنيف</label>
      <select className="field-input" value={form.category} onChange={set("category")}>
        {Object.entries(EXPENSE_CATEGORY_LABELS).map(([k, l]) => <option key={k} value={k}>{l}</option>)}
      </select>

      <label className="field-label">الوصف</label>
      <input className="field-input" value={form.description} onChange={set("description")}
        placeholder="مثال: فاتورة كهرباء سبتمبر" />

      <label className="field-label">المستفيد (اختياري)</label>
      <input className="field-input" value={form.beneficiary} onChange={set("beneficiary")} />

      <label className="field-label">المبلغ (د.ل)</label>
      <input className="field-input" type="number" min="0" value={form.amount} onChange={set("amount")} />

      <label className="field-label">تاريخ المصروف</label>
      <input className="field-input" type="date" value={form.expenseDate} onChange={set("expenseDate")} />

      <label className="field-label">طريقة الصرف</label>
      <div className="tile-row-inline">
        {[["cash", "نقدًا"], ["transfer", "حوالة مصرفية"]].map(([v, l]) => (
          <button key={v} className={"chip" + (form.method === v ? " chip-active" : "")}
            onClick={() => setForm((f) => ({ ...f, method: v }))}>{l}</button>
        ))}
      </div>

      <p className="voucher-balance-line">
        يُخصم من: <b>{treasuryLabel}</b>
      </p>

      {create.error && <p className="field-error">{create.error}</p>}

      <div className="add-form-actions">
        <button className="btn-primary" disabled={!valid || create.pending}
          onClick={() => create.run().then(() => { onDone(); onClose(); }).catch(() => {})}>
          {create.pending ? "جارٍ الحفظ…" : "حفظ المصروف"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

function TransferForm({ onClose, onDone }) {
  const [form, setForm] = useState({ fromCode: "sales", toCode: "main", amount: "", note: "" });
  const create = useAction(() => api.transfers({
    fromCode: form.fromCode, toCode: form.toCode,
    amount: Number(form.amount), note: form.note || undefined,
  }));
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  return (
    <div className="detail-card voucher-form">
      <h2 className="subsection-heading">تحويل بين الخزائن</h2>
      <p className="hint">يُستخدم عند استلام موظف المالية للمبالغ المحصّلة وترحيلها للخزينة الرئيسية.</p>

      <label className="field-label">من</label>
      <select className="field-input" value={form.fromCode} onChange={set("fromCode")}>
        <option value="sales">خزينة المبيعات</option><option value="main">الخزينة الرئيسية</option>
      </select>
      <label className="field-label">إلى</label>
      <select className="field-input" value={form.toCode} onChange={set("toCode")}>
        <option value="main">الخزينة الرئيسية</option><option value="sales">خزينة المبيعات</option>
      </select>
      <label className="field-label">المبلغ (د.ل)</label>
      <input className="field-input" type="number" min="0" value={form.amount} onChange={set("amount")} />
      <label className="field-label">ملاحظة</label>
      <input className="field-input" value={form.note} onChange={set("note")} placeholder="اختياري" />

      {create.error && <p className="field-error">{create.error}</p>}
      <div className="add-form-actions">
        <button className="btn-primary" disabled={create.pending || !form.amount || form.fromCode === form.toCode}
          onClick={() => create.run().then(() => { onDone(); onClose(); }).catch(() => {})}>
          {create.pending ? "جارٍ التحويل…" : "تأكيد التحويل"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

