/* --------------------------- سجل التدقيق --------------------------- */

function AuditLogView({ can }) {
  const [entityType, setEntityType] = useState("");
  const [query, setQuery] = useState("");
  const { data, loading, error, reload } = useFetch(
    (s) => api.auditLogs({ entityType: entityType || undefined, search: query.trim() || undefined }, s),
    [entityType, query]
  );

  if (!can("accounts.approve")) {
    return <div className="screen"><Empty icon={History} text="لا تملك صلاحية الاطلاع على سجل التدقيق" /></div>;
  }

  const types = ["", "order", "product", "supplier", "customer", "employee", "order_supplier", "section"];
  const typeLabels = {
    "": "الكل", order: "الطلبيات", product: "الأصناف", supplier: "الموردون",
    customer: "العملاء", employee: "الموظفون", order_supplier: "فواتير الموردين", section: "الأقسام",
  };

  return (
    <div className="screen">
      <div className="toolbar-row">
        <div className="chip-row">
          {types.map((t) => (
            <button key={t} className={"chip" + (entityType === t ? " chip-active" : "")}
              onClick={() => setEntityType(t)}>{typeLabels[t]}</button>
          ))}
        </div>
        <SearchBar inline value={query} onChange={setQuery} placeholder="ابحث بالاسم أو نوع العملية..." />
      </div>

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !data?.length ? <Empty icon={History} text="لا توجد عمليات مسجّلة" />
       : (
        <table className="data-table">
          <thead><tr><th>التاريخ والوقت</th><th>بواسطة</th><th>العملية</th><th>العنصر</th></tr></thead>
          <tbody>
            {data.map((l) => (
              <tr key={l.id}>
                <td className="cell-muted">{new Date(l.created_at).toLocaleString("ar")}</td>
                <td className="cell-id">{l.actor_name}</td>
                <td className="cell-muted" dir="ltr" style={{ textAlign: "right" }}>{l.action}</td>
                <td className="cell-muted">{l.entity_label || "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

